<template id="gemini-entry-template">
    <details class="entry-card gemini-entry">
        <summary class="entry-header">
            <div class="entry-header-top">
                <!-- Icon swapped to agent SVG via JS when isAgent=true -->
                <span class="entry-icon entry-icon-gemini" data-i18n-title="configureApiKeyTooltip"
                    ><svg width="24" height="24" aria-hidden="true">
                        <use href="#icon-gemini"></use>
                    </svg></span
                >
                <div class="entry-actions">
                    <!-- Resend button (left of read-aloud) -->
                    <div class="resend-entry-btn action-btn" data-i18n-title="resendQuery">
                        <svg class="icon-resume" width="20" height="20">
                            <use href="#icon-resume"></use>
                        </svg>
                    </div>
                    <div class="read-aloud-btn action-btn" data-i18n-title="readAloud">
                        <svg class="icon-play" width="20" height="20">
                            <use href="#icon-play"></use>
                        </svg>
                        <svg class="icon-pause" width="20" height="20">
                            <use href="#icon-pause"></use>
                        </svg>
                        <!-- New icon-resume SVG -->
                        <svg class="icon-resume" width="20" height="20">
                            <use href="#icon-refresh"></use>
                        </svg>
                        <svg class="icon-stop" width="20" height="20">
                            <use href="#icon-stop"></use>
                        </svg>
                    </div>
                    <div class="edit-entry-btn action-btn" data-i18n-title="editGeminiQuery">
                        <svg width="20" height="20">
                            <use href="#icon-edit"></use>
                        </svg>
                    </div>
                    <div class="download-entry-btn action-btn" data-i18n-title="downloadGeminiEntry">
                        <svg width="20" height="20">
                            <use href="#icon-download"></use>
                        </svg>
                    </div>
                    <div class="copy-entry-btn action-btn" data-i18n-title="copyGeminiResponse">
                        <svg width="20" height="20">
                            <use href="#icon-copy"></use>
                        </svg>
                    </div>
                    <div class="delete-entry-btn action-btn" data-i18n-title="deleteGeminiQuery">
                        <svg width="20" height="20">
                            <use href="#icon-close-stroke"></use>
                        </svg>
                    </div>
                </div>
            </div>
            <h2 data-original-text="" class="entry-title"></h2>
        </summary>
        <!-- Agent steps: shown live during agent execution, hidden for normal entries -->
        <div class="agent-steps hidden"></div>
        <div class="entry-content"></div>
        <div class="entry-footer"></div>
    </details>
</template>

