<template id="cookie-entry-template">
    <details class="cookie-entry-card" open>
        <summary>
            <span class="cookie-name"></span>
            <div class="delete-cookie-btn action-btn" data-i18n-title="deleteCookie">&times;</div>
        </summary>
        <div class="cookie-form-grid">
            <div class="form-group full-width">
                <div class="field-label" data-i18n="cookieValue"></div>
                <textarea rows="3" class="cookie-value"></textarea>
            </div>
            <div class="form-group">
                <div class="field-label" data-i18n="cookieDomain"></div>
                <input type="text" class="cookie-domain" />
            </div>
            <div class="form-group">
                <div class="field-label" data-i18n="cookiePath"></div>
                <input type="text" class="cookie-path" />
            </div>
            <div class="form-group">
                <div class="field-label" data-i18n="cookieExpiration"></div>
                <div class="datetime-row cookie-datetime-row">
                    <div class="field-container">
                        <div class="custom-input-trigger cookie-expiration-date-trigger">
                            <span class="val-placeholder">YYYY-MM-DD</span>
                        </div>
                    </div>
                    <div class="field-container time-width">
                        <div class="custom-input-trigger time-trigger cookie-expiration-time-trigger">00:00</div>
                    </div>
                </div>
            </div>
            <div class="form-group">
                <div class="field-label" data-i18n="cookieSameSite"></div>
                <select class="cookie-samesite">
                    <button type="button">
                        <selectedcontent></selectedcontent>
                        <svg
                            class="picker-icon"
                            width="10"
                            height="10"
                            viewBox="0 0 24 24"
                            fill="none"
                            stroke="currentColor"
                            stroke-width="3"
                            stroke-linecap="round"
                            stroke-linejoin="round"
                            aria-hidden="true"
                            focusable="false"
                        >
                            <path d="m6 9 6 6 6-6" />
                        </svg>
                    </button>
                    <option value="no_restriction">None</option>
                    <option value="lax">Lax</option>
                    <option value="strict">Strict</option>
                </select>
            </div>
            <div class="form-group checkbox-group">
                <label style="display: flex; align-items: center; gap: 8px; margin: 0; cursor: pointer;"
                    ><input type="checkbox" class="cookie-httponly" /><span data-i18n="cookieHttpOnly"></span></label
                >
            </div>
            <div class="form-group checkbox-group">
                <label style="display: flex; align-items: center; gap: 8px; margin: 0; cursor: pointer;"
                    ><input type="checkbox" class="cookie-secure" /><span data-i18n="cookieSecure"></span></label
                >
            </div>
        </div>
    </details>
</template>

