<template id="overflow-actions-template">
    <div class="overflow-actions-container">
        <div class="overflow-btn action-btn" role="button" tabindex="0" data-i18n-title="showHiddenActions">
            <svg width="14" height="14">
                <use href="#icon-more-vertical"></use>
            </svg>
        </div>
    </div>
</template>

<template id="overflow-popup-template">
    <div class="overflow-popup">
        <div class="overflow-bridge"></div>
        <!-- Popup elements will be generated dynamically -->
    </div>
</template>

<template id="overflow-popup-item-template">
    <div class="overflow-popup-item" role="button" tabindex="0">
        <span class="overflow-item-icon"></span>
        <span class="overflow-item-text"></span>
    </div>
</template>

<template id="context-menu-template">
    <div class="context-menu-overlay">
        <div class="context-menu" role="menu">
            <ul class="context-menu-list"></ul>
        </div>
    </div>
</template>

<template id="context-menu-item-template">
    <li class="context-menu-item" role="menuitem" tabindex="0">
        <span class="context-menu-icon"></span>
        <span class="context-menu-text"></span>
        <span class="context-menu-counter"></span>
    </li>
</template>

<template id="gemini-model-dropdown-template">
    <div class="gemini-model-dropdown">
        <div class="dropdown-search-container">
            <span class="search-icon">
                <svg width="14" height="14">
                    <use href="#icon-search"></use>
                </svg>
            </span>
            <label for="gemini-model-search-input" class="visually-hidden" data-i18n="searchModelPlaceholder"></label>
            <input
                type="search"
                id="gemini-model-search-input"
                data-i18n-placeholder="searchModelPlaceholder"
                autocomplete="off"
            />
        </div>
        <ul></ul>
    </div>
</template>

<template id="gemini-model-item-template">
    <li class="gemini-model-item">
        <button type="button"></button>
    </li>
</template>

<template id="generic-list-item-template">
    <div class="generic-item tab-item" role="link" tabindex="0">
        <img src="" alt="" class="favicon" />
        <div class="item-info">
            <span class="item-title"></span>
            <span class="item-url"></span>
            <span class="item-meta"></span>
        </div>
        <button type="button" class="delete-item-btn action-btn" data-i18n-title="deleteButton">
            <svg width="20" height="20">
                <use href="#icon-close-stroke"></use>
            </svg>
        </button>
    </div>
</template>

<template id="group-item-template">
    <div class="group-actions">
        <div class="backup-btn action-btn"><svg width="14" height="14"><use href="#icon-backup"></use></svg></div>
        <div class="restore-btn action-btn"><svg width="14" height="14"><use href="#icon-restore"></use></svg></div>
        <div class="pin-btn action-btn"><svg width="14" height="14"><use href="#icon-pin"></use></svg></div>
        <div class="hide-group-btn action-btn"><svg width="14" height="14"><use href="#icon-eye"></use></svg></div>
        <div class="create-rule-btn action-btn">
            <svg width="14" height="14"><use href="#icon-create-rule"></use></svg>
        </div>
        <div class="add-to-rule-btn action-btn">
            <svg width="14" height="14"><use href="#icon-add-to-rule"></use></svg>
        </div>
        <div class="capture-group-btn action-btn">
            <svg width="14" height="14"><use href="#icon-screenshot"></use></svg>
        </div>
        <div class="copy-group-urls-btn action-btn">
            <svg width="14" height="14"><use href="#icon-copy"></use></svg>
        </div>
        <div class="delete-group-btn action-btn"><svg width="14" height="14"><use href="#icon-trash"></use></svg></div>
    </div>
</template>

<template id="domain-subgroup-template">
    <div class="subgroup-actions">
        <div class="create-rule-btn action-btn">
            <svg width="14" height="14"><use href="#icon-create-rule"></use></svg>
        </div>
        <div class="add-to-rule-btn action-btn">
            <svg width="14" height="14"><use href="#icon-add-to-rule"></use></svg>
        </div>
        <div class="copy-subgroup-urls-btn action-btn">
            <svg width="14" height="14"><use href="#icon-copy"></use></svg>
        </div>
        <div class="delete-subgroup-btn action-btn">
            <svg width="14" height="14"><use href="#icon-trash"></use></svg>
        </div>
    </div>
</template>

<template id="tab-item-template">
    <div class="tab-actions">
        <div class="gemini-summary-btn action-btn">
            <svg width="14" height="14"><use href="#icon-summary"></use></svg>
        </div>
        <div class="read-page-btn action-btn">
            <svg width="14" height="14"><use href="#icon-read-aloud"></use></svg>
        </div>
        <div class="bookmark-btn action-btn"><svg width="14" height="14"><use href="#icon-bookmark"></use></svg></div>
        <div class="download-files-btn action-btn">
            <svg width="14" height="14"><use href="#icon-download"></use></svg>
        </div>
        <div class="pip-btn action-btn"><svg width="14" height="14"><use href="#icon-pip"></use></svg></div>
        <div class="video-pip-btn action-btn">
            <svg width="14" height="14"><use href="#icon-video-pip"></use></svg>
        </div>
        <div class="popup-btn action-btn"><svg width="14" height="14"><use href="#icon-popup"></use></svg></div>
        <div class="split-screen-btn action-btn">
            <svg width="14" height="14"><use href="#icon-split-screen"></use></svg>
        </div>
        <div class="open-in-panel-btn action-btn">
            <svg width="14" height="14"><use href="#icon-open-panel"></use></svg>
        </div>
        <div class="page-mode-btn action-btn"><svg width="14" height="14"><use href="#icon-page-mode"></use></svg></div>
        <div class="qr-code-btn action-btn"><svg width="14" height="14"><use href="#icon-qr"></use></svg></div>
        <div class="edit-cookies-btn action-btn"><svg width="14" height="14"><use href="#icon-cookie"></use></svg></div>
        <div class="copy-tab-url-btn action-btn"><svg width="14" height="14"><use href="#icon-copy"></use></svg></div>
        <div class="delete-tab-btn action-btn"><svg width="14" height="14"><use href="#icon-close"></use></svg></div>
    </div>
</template>

<template id="bookmark-item-template">
    <div class="bookmark-item-actions">
        <div class="copy-btn action-btn"><svg width="14" height="14"><use href="#icon-copy"></use></svg></div>
        <div class="edit-btn action-btn"><svg width="14" height="14"><use href="#icon-edit"></use></svg></div>
        <div class="delete-btn action-btn"><svg width="14" height="14"><use href="#icon-trash"></use></svg></div>
    </div>
</template>

<template id="bookmark-folder-template">
    <div class="bookmark-folder-actions">
        <div class="add-folder-btn action-btn">
            <svg width="16" height="16"><use href="#icon-add-folder"></use></svg>
        </div>
        <div class="open-all-btn action-btn"><svg width="14" height="14"><use href="#icon-open-all"></use></svg></div>
        <div class="edit-folder-btn action-btn"><svg width="14" height="14"><use href="#icon-edit"></use></svg></div>
        <div class="delete-folder-btn action-btn"><svg width="14" height="14"><use href="#icon-trash"></use></svg></div>
    </div>
</template>

<template id="gallery-item-template">
    <div class="gallery-item">
        <img src="" alt="Screenshot" loading="lazy" class="gallery-image" />
        <span class="gallery-full-page-badge" data-i18n="fullPageBadge"></span>
        <div class="gallery-item-info">
            <p class="gallery-item-title"></p>
        </div>
        <button type="button" class="gallery-action-btn gallery-pin-btn" data-i18n-title="pinScreenshot">
            <svg width="20" height="20">
                <use href="#icon-archive-note"></use>
            </svg>
        </button>
        <button type="button" class="gallery-action-btn gallery-ocr-btn" data-i18n-title="ocrScreenshot">
            <svg width="18" height="18">
                <use href="#icon-summary"></use>
            </svg>
        </button>
        <div class="gallery-item-actions">
            <button type="button" class="gallery-action-btn copy-btn" data-i18n-title="copy">
                <svg width="14" height="14">
                    <use href="#icon-copy"></use>
                </svg>
            </button>
            <button type="button" class="gallery-action-btn download-btn" data-i18n-title="download">
                <svg width="18" height="18">
                    <use href="#icon-download-all"></use>
                </svg>
            </button>
            <button type="button" class="gallery-action-btn delete-btn" data-i18n-title="delete">
                <svg width="18" height="18">
                    <use href="#icon-trash"></use>
                </svg>
            </button>
        </div>
    </div>
</template>
